<script>
	// A comment before else selects the other if printer; the consequent still takes
	// adjustClause, so it stays inline at 100 and drops to its own line at 101
	if (aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa) fnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn();
	// c1
	else g();

	if (aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa)
		fnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn();
	// c2
	else g();
</script>
